data: {"index":1,"delta":{"text":" planet’s climate has fluctuated naturally over millions of years, the current period of warming is occurring at an unprecedented rate and","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" is unequivocally driven by human activity.\n\n### Causes: The Greenhouse Effect\nThe primary driver of modern climate change is the \"","type":"text"},"event_type":"step.delta"}

