data: {"index":1,"delta":{"text":"—act like the glass walls of a greenhouse, trapping solar heat and preventing it from escaping back into space.\n\nSince","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" the Industrial Revolution, human activities have drastically increased the concentration of these gases. The burning of fossil fuels (coal, oil, and natural gas","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":") for electricity, heat, and transportation is the largest source of CO2 emissions. Deforestation also plays a critical role; trees","type":"text"},"event_type":"step.delta"}

