data: {"index":1,"delta":{"text":" act as \"carbon sinks,\" absorbing CO2 from the atmosphere. When forests are cleared or burned, that stored carbon is released back","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" into the air. Additionally, industrial agriculture and livestock production contribute significantly to methane emissions, which are far more potent than CO2","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" at trapping heat in the short term.\n\n### Evidence: A Warming World\nThe evidence for climate change is extensive and observed","type":"text"},"event_type":"step.delta"}

